I'll show you a safely re-runnable migration script using idempotency checks.

**PostgreSQL SQL Migration** (`001_split_full_name.sql`):

```sql
-- Add new columns if they don't exist
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_name = 'users' AND column_name = 'first_name'
  ) THEN
    ALTER TABLE users ADD COLUMN first_name VARCHAR(255);
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_name = 'users' AND column_name = 'last_name'
  ) THEN
    ALTER TABLE users ADD COLUMN last_name VARCHAR(255);
  END IF;
END
$$;

-- Backfill from full_name where not already filled
UPDATE users
SET 
  first_name = COALESCE(first_name, TRIM(SPLIT_PART(full_name, ' ', 1))),
  last_name = COALESCE(last_name, TRIM(SUBSTRING(full_name FROM POSITION(' ' IN full_name) + 1)))
WHERE full_name IS NOT NULL
  AND (first_name IS NULL OR last_name IS NULL);

-- For single names (no space), use full_name as first_name
UPDATE users
SET
  first_name = COALESCE(first_name, full_name),
  last_name = COALESCE(last_name, '')
WHERE full_name IS NOT NULL
  AND full_name NOT LIKE '% %'
  AND first_name IS NULL;

-- Drop old column only after verified—comment out until ready
-- ALTER TABLE users DROP COLUMN full_name;
```

**Node.js/JavaScript Migration** (using db-migrate or similar):

```javascript
// migrations/001-split-full-name.js
exports.up = async function(db) {
  const connection = db.getConnection();

  try {
    // Check if already migrated
    const result = await connection.query(`
      SELECT column_name FROM information_schema.columns 
      WHERE table_name = 'users' AND column_name = 'first_name'
    `);

    if (result.length > 0) {
      console.log('Migration already applied, skipping...');
      return;
    }

    // Add columns
    await connection.query('ALTER TABLE users ADD COLUMN first_name VARCHAR(255)');
    await connection.query('ALTER TABLE users ADD COLUMN last_name VARCHAR(255)');

    // Backfill: split on first space
    await connection.query(`
      UPDATE users
      SET 
        first_name = TRIM(SUBSTRING_INDEX(full_name, ' ', 1)),
        last_name = TRIM(SUBSTRING_INDEX(full_name, ' ', -1))
      WHERE full_name IS NOT NULL
        AND CHAR_LENGTH(TRIM(full_name)) > 0
    `);

    console.log('Migration completed successfully');
  } catch (err) {
    console.error('Migration failed:', err.message);
    throw err;
  }
};

exports.down = async function(db) {
  // Rollback: drop new columns, restore old data
  const connection = db.getConnection();
  await connection.query('ALTER TABLE users DROP COLUMN first_name, DROP COLUMN last_name');
};
```

**Key safety features:**
- **Idempotent** — checks if columns exist before adding (safe to re-run)
- **Non-destructive** — keeps `full_name` column until you manually drop it
- **Handles edge cases** — single names, NULLs, trimming whitespace
- **Reversible** — `DOWN` migration included; can rollback if needed
- **Readable split** — uses space as delimiter; adjust if you need smarter parsing (e.g., "John Q Public" → "John" / "Q Public")

For production: test in staging first, back up the table, and review the backfilled data before dropping `full_name`.
